'use strict';
const fs = require('fs');
const path = require('path');

const FILES = path.join(__dirname, '..', 'files');

// Route table; the HTTP layer calls handle(route, query).
const routes = {
  health: () => ({ status: 200, body: 'ok' }),
  download: (query) => {
    const p = path.join(FILES, String(query.name));
    if (!fs.existsSync(p)) return { status: 404, body: 'not found' };
    return { status: 200, body: fs.readFileSync(p, 'utf8') };
  },
};

function handle(route, query = {}) {
  const fn = routes[route];
  return fn ? fn(query) : { status: 404, body: 'no route' };
}

module.exports = { handle, routes };

