const test = require('node:test');
const assert = require('node:assert');
const { handle } = require('../src/server');

test('health', () => assert.equal(handle('health').body, 'ok'));
test('download', () => assert.equal(handle('download', { name: 'readme.txt' }).body, 'Welcome.\n'));
test('missing file', () => assert.equal(handle('download', { name: 'nope.txt' }).status, 404));
